const clean = v => (v ? v.toString().trim() : '');
const onlyNumbers = v => clean(v).replace(/\D/g, '');

const formatarCPF = v => {
  const num = onlyNumbers(v);
  return `="${num.padStart(11, '0').slice(-11)}"`;
};

const formatarCEP = v => {
  const num = onlyNumbers(v);
  return num.padStart(8, '0').slice(0, 8);
};

const formatarTelefone = v => {
  if (!v) return '';
  const raw = typeof v === 'number' ? Math.round(v).toString() : v.toString();
  return `="${raw.replace(/[\D\s\-\(\)]/g, '')}"`;
};

const formatarValor = v => {
  if (!v) return '0,00';
  let n = typeof v === 'number' ? v : parseFloat(v.toString().replace(',', '.'));
  if (isNaN(n)) n = 0;
  return n.toFixed(2).replace('.', ',');
};

const formatarData = v => {
  if (!v) return '';
  const s = clean(v);
  if (/^\d{8}$/.test(s)) return s;
  const d = new Date(s);
  if (!isNaN(d)) {
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    return `${y}${m}${day}`;
  }
  return '';
};

const limparEndereco = v => clean(v).replace(/[.,;:]/g, '');

let inputData = $input.all().map(i => i.json);

const output = inputData.map(row => {
  const values = Object.values(row);

  const matricula  = clean(values[1]);
  const nome       = clean(values[2]);
  const curso      = clean(values[0]);
  const cpf        = formatarCPF(values[4]);
  const endereco   = limparEndereco(values[8]);
  const bairro     = clean(values[11]);
  const cidade     = clean(values[12]);
  const cep        = formatarCEP(values[10]);
  const estado     = clean(values[13]);
  const telefone   = formatarTelefone(values[14]);
  const vencimento = formatarData(values[18]);
  const valor      = formatarValor(values[19]);
  const email      = clean(values[16]);

  return {
    json: {
      A: matricula,
      B: nome,
      C: curso,
      D: cpf,
      E: '',
      F: endereco,
      G: bairro,
      H: cidade,
      I: cep,
      J: estado,
      K: '',
      L: telefone,
      M: nome,
      N: 'MENSALIDADE',
      O: vencimento,
      P: valor,
      Q: email
    }
  };
});

return output;
